<?php $edit=!empty($resolucion); $action=$edit?'admin/resoluciones/editar/'.$resolucion->id:'admin/resoluciones/crear'; $grupoInicial=(int)$this->input->get('grupo_id',TRUE); ?><div class="card"><div class="card-body"><?php if(validation_errors()): ?><div class="alert alert-danger"><?= validation_errors() ?></div><?php endif; ?><?= form_open_multipart($action) ?><div class="row g-3"><div class="col-md-6"><label class="form-label">Grupo *</label><select name="grupo_id" class="form-select select2" required><option value="">Seleccione</option><?php foreach($grupos as $g): ?><option value="<?= $g->id ?>" <?= set_select('grupo_id',$g->id,$edit ? $resolucion->grupo_id==$g->id : $grupoInicial==$g->id) ?>>GR-<?= str_pad($g->consecutivo,4,'0',STR_PAD_LEFT) ?> · <?= html_escape($g->descripcion) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Fecha de resolución *</label><input type="date" name="fecha_resolucion" max="<?= (new DateTimeImmutable('today',new DateTimeZone('America/Bogota')))->modify('+30 days')->format('Y-m-d') ?>" class="form-control" value="<?= set_value('fecha_resolucion',$edit?$resolucion->fecha_resolucion:'') ?>" required></div><div class="col-12"><label class="form-label">Título *</label><input name="titulo" class="form-control" value="<?= set_value('titulo',$edit?$resolucion->titulo:'') ?>" maxlength="255" required></div><div class="col-md-6"><label class="form-label">Archivo PDF <?= $edit?'(opcional para reemplazar)':'' ?></label><input type="file" name="archivo" accept="application/pdf" class="form-control"><?php if($edit && $resolucion->archivo): ?><small>Actual: <?= html_escape($resolucion->archivo) ?></small><?php endif; ?></div><div class="col-md-6"><label class="form-label">URL alternativa</label><input type="url" name="url" class="form-control" value="<?= set_value('url',$edit?$resolucion->url:'') ?>" placeholder="https://..."></div><div class="col-md-6"><label class="form-label">Imagen previa (opcional)</label><input type="file" name="imagen" accept="image/jpeg,image/png,image/webp" class="form-control"><?php if($edit && $resolucion->imagen): ?><img class="img-thumbnail mt-2 preview-mini" src="<?= base_url($resolucion->imagen) ?>"><?php endif; ?></div><?php if($edit): ?><div class="col-md-6 d-flex align-items-center"><div class="form-check mt-4"><input class="form-check-input" type="checkbox" name="activo" value="1" id="activo" <?= $resolucion->activo?'checked':'' ?>><label class="form-check-label" for="activo">Resolución activa/publicada</label></div></div><?php endif; ?></div><div class="form-text mt-3">Debe existir al menos un PDF cargado o una URL.</div><button class="btn btn-corponor mt-3">Guardar resolución</button><?= form_close() ?></div></div>
